-- Acquisition costs: private backend-only drafts, documents, packaging and audit.

BEGIN;

CREATE TABLE IF NOT EXISTS public."compras_conferencias" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loja_id" bigint NOT NULL,
  "local_estoque_id" bigint,
  "usuario_criacao_id" bigint NOT NULL,
  "usuario_confirmacao_id" bigint,
  "nota_entrada_id" bigint,
  "identificador" text NOT NULL,
  "origem" text NOT NULL,
  "status" text NOT NULL DEFAULT 'RASCUNHO',
  "versao" integer NOT NULL DEFAULT 1,
  "estado_json" text NOT NULL,
  "original_json" text NOT NULL,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text,
  "confirmado_em" text,
  FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("local_estoque_id") REFERENCES public."locais_estoque" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("usuario_criacao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("usuario_confirmacao_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("nota_entrada_id") REFERENCES public."notas_entrada" ("id") DEFERRABLE INITIALLY DEFERRED,
  UNIQUE(identificador),
  UNIQUE(nota_entrada_id),
  CHECK(status IN ('RASCUNHO','CONFIRMADA'))
);

ALTER TABLE public."compras_conferencias" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public."compras_documentos" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "conferencia_id" bigint NOT NULL,
  "nome" text NOT NULL,
  "mime" text NOT NULL,
  "sha256" text NOT NULL,
  "conteudo_base64" text NOT NULL,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  FOREIGN KEY ("conferencia_id") REFERENCES public."compras_conferencias" ("id") DEFERRABLE INITIALLY DEFERRED,
  UNIQUE(conferencia_id,sha256)
);

ALTER TABLE public."compras_documentos" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public."compras_embalagens" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loja_id" bigint NOT NULL,
  "fornecedor_id" bigint NOT NULL,
  "produto_id" bigint NOT NULL,
  "codigo_fornecedor" text,
  "unidades_embalagem" numeric NOT NULL,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  "atualizado_em" text,
  FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED,
  UNIQUE(loja_id,fornecedor_id,produto_id),
  CHECK(unidades_embalagem > 0)
);

ALTER TABLE public."compras_embalagens" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public."compras_custos_historico" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "loja_id" bigint NOT NULL,
  "produto_id" bigint,
  "fornecedor_id" bigint,
  "conferencia_id" bigint,
  "usuario_id" bigint NOT NULL,
  "origem" text NOT NULL,
  "custo_anterior" text,
  "custo_novo" text,
  "quantidade" text,
  "componentes_json" text NOT NULL,
  "justificativa" text,
  "criado_em" text DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'),
  FOREIGN KEY ("loja_id") REFERENCES public."lojas" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("produto_id") REFERENCES public."produtos" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("fornecedor_id") REFERENCES public."fornecedores" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("conferencia_id") REFERENCES public."compras_conferencias" ("id") DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY ("usuario_id") REFERENCES public."usuarios" ("id") DEFERRABLE INITIALLY DEFERRED
);

ALTER TABLE public."compras_custos_historico" ENABLE ROW LEVEL SECURITY;

DO $security$
DECLARE t text; r text; tinha_create boolean;
BEGIN
  FOREACH t IN ARRAY ARRAY['compras_conferencias','compras_documentos','compras_embalagens','compras_custos_historico'] LOOP
    EXECUTE format('REVOKE ALL PRIVILEGES ON TABLE public.%I FROM PUBLIC',t);
    FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
      IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
        EXECUTE format('REVOKE ALL PRIVILEGES ON TABLE public.%I FROM %I',t,r);
        EXECUTE format('REVOKE ALL PRIVILEGES ON SEQUENCE public.%I FROM %I',t||'_id_seq',r);
      END IF;
    END LOOP;
    EXECUTE format('REVOKE ALL PRIVILEGES ON SEQUENCE public.%I FROM PUBLIC',t||'_id_seq');
    IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='nosso_mercadinho_api') THEN
      tinha_create:=has_schema_privilege('nosso_mercadinho_api','public','CREATE');
      IF NOT tinha_create THEN GRANT CREATE ON SCHEMA public TO nosso_mercadinho_api; END IF;
      EXECUTE format('ALTER TABLE public.%I OWNER TO nosso_mercadinho_api',t);
      IF NOT tinha_create THEN REVOKE CREATE ON SCHEMA public FROM nosso_mercadinho_api; END IF;
    END IF;
  END LOOP;
END $security$;

COMMIT;
